1	#!/usr/bin/env node
2	/**
3	 * 서버 내 멀티 Claude 에이전트 통신 시스템
4	 * 같은 서버에서 여러 Claude 인스턴스가 메시지 교환
5	 */
6	
7	const Anthropic = require("@anthropic-ai/sdk");
8	const EventEmitter = require("events");
9	
10	// ============= 메시지 버스 (IPC) =============
11	class MessageBus extends EventEmitter {
12	  constructor() {
13	    super();
14	    this.agents = new Map();
15	    this.messageLog = [];
16	  }
17	
18	  register(agentId, agent) {
19	    this.agents.set(agentId, agent);
20	    console.log(`✅ 에이전트 등록: ${agentId}`);
21	  }
22	
23	  async send(fromId, toId, message) {
24	    const envelope = {
25	      timestamp: new Date().toISOString(),
26	      from: fromId,
27	      to: toId,
28	      message,
29	      id: `msg_${Date.now()}_${Math.random().toString(36).slice(2)}`
30	    };
31	
32	    this.messageLog.push(envelope);
33	    console.log(`\n📨 [${fromId}] → [${toId}]`);
34	    console.log(`   메시지: ${message.substring(0, 100)}...`);
35	
36	    // 수신자에게 메시지 전달
37	    const recipient = this.agents.get(toId);
38	    if (recipient) {
39	      await recipient.receiveMessage(envelope);
40	    } else {
41	      console.warn(`⚠️  수신자 ${toId}를 찾을 수 없습니다`);
42	    }
43	
44	    return envelope;
45	  }
46	
47	  getLog() {
48	    return this.messageLog;
49	  }
50	}

